'use strict';
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(value,digits=2)=>value==null?'—':Number(value).toLocaleString('en-US',{maximumFractionDigits:digits,minimumFractionDigits:digits});
const count=value=>value==null?'—':Number(value).toLocaleString('en-US',{maximumFractionDigits:0});
const short=value=>value==null?'—':value>=1e9?fmt(value/1e9,2)+' B':value>=1e6?fmt(value/1e6,2)+' M':value>=1e3?fmt(value/1e3,1)+' K':count(value);
const statusNames={running:'运行中',stopping:'正在停止',stopped:'已停止',completed:'已完成',failed:'运行失败',interrupted:'运行中断'};
const phaseNames={build:'检查构建与源码版本',starting:'准备运行',generate:'Python 生成数据',observe:'C++ 逐阶段观测',verify:'校验输出',baseline:'串行运行无埋点对照',done:'输出已保存'};
let serviceClosing=false;
let boot=null,state=null,runId=null,view='overview',selectedStage='market_write',selectedTable='market_quotes',dataKind='input',dataTable='market',dataTick=0,submitting=false,refreshing=false;
const pages={profiles:['函数热点','函数热点','采样账户估值、账户转列和行情写入的函数调用栈。'],overview:['实验总览','实验总览','运行参数、阶段性能与输出校验。'],pipeline:['数据处理流程','数据处理流程','各阶段的性能指标、输入规模和对应源码。'],data:['数据源与输出','数据源与输出','Python 模拟输入与已落盘的数据预览。'],schema:['表结构与字段','表结构与字段','支持的表、字段类型、主键及约束。'],evidence:['技术实现证据','技术实现证据','源码、编译报告与运行观测。'],history:['运行记录','运行记录','历史实验的参数、状态与结果。']};
async function api(path,options){const response=await fetch(path,options);const value=await response.json();if(!response.ok)throw Error(value.error||'请求失败');return value;}
function error(message){if(serviceClosing)return;$('#error').hidden=!message;$('#error').textContent=message||'';}
function metric(title,value,unit,note,tag=''){return `<div class="metric panel"><div class="metric-name">${esc(title)}<span>${esc(tag)}</span></div><div class="metric-value">${value}<small>${esc(unit)}</small></div><div class="metric-note">${esc(note)}</div></div>`;}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`;}
function empty(text){return `<div class="empty"><div class="empty-symbol">{ · }</div>${esc(text)}</div>`;}
function stageInfo(id){return boot.stages.find(x=>x.id===id);}
function measured(id){return state?.trace?.stages?.[id];}
function groupTime(id){const ids=id==='market_write'?['txn_begin','market_transform','market_write','trades_transform','trades_write','accounts_transform','accounts_write','txn_commit']:id==='account_value'?['account_fills','account_value']:[id];const values=ids.map(measured).filter(Boolean);return values.length?values.reduce((sum,value)=>sum+value.wall_ms,0):null;}
function stageStatus(id){const event=state?.trace?.current;if(event?.stage===id&&event.kind==='start'&&['running','stopping'].includes(state?.job?.status))return '运行中';if(event?.stage===id&&event.kind==='error')return '失败';return measured(id)?'已观测':'未执行';}
function eventLog(){const events=(state?.trace?.events||[]).filter(e=>e.stage&&['end','error'].includes(e.kind)).slice(-10).reverse();return `<section class="panel" style="margin-top:20px"><div class="section-heading"><h2>最近阶段事件</h2><span class="chip">${state?.trace?.event_count||0} EVENTS</span></div>${events.length?`<div class="table-wrap"><table><thead><tr><th>相对时间 / ms</th><th>tick</th><th>阶段</th><th>状态</th><th>耗时 / ms</th></tr></thead><tbody>${events.map(e=>`<tr><td class="mono">${fmt(e.at_ms)}</td><td class="mono">${e.tick<0?'准备':e.tick}</td><td>${esc(stageInfo(e.stage)?.title||e.stage)}</td><td>${e.kind==='error'?'失败':'完成'}</td><td class="mono">${fmt(e.metrics?.wall_ms,3)}</td></tr>`).join('')}</tbody></table></div>`:empty('等待阶段事件。')}</section>`;}

function sourceBlock(source,limit=18){const lines=source.text.split('\n').slice(0,limit);return `<div class="source-label"><span>${esc(source.file)}:${source.line}</span><button class="text-button" data-source="${esc(source.file)}" data-line="${source.line}">查看完整源码 ↗</button></div><pre class="code">${lines.map((text,i)=>`<span class="line"><span class="line-no">${i+source.line}</span>${esc(text)}</span>`).join('')}</pre>`;}
function total(){const entries=Object.entries(state?.trace?.stages||{}).filter(([id])=>!['generate','pace_wait'].includes(id));const value={wall_ms:0,cycles:0,instructions:0,valid:entries.length>0};for(const [,s]of entries){value.wall_ms+=s.wall_ms;if(s.cycles==null||s.instructions==null)value.valid=false;else{value.cycles+=s.cycles;value.instructions+=s.instructions;}}if(!value.valid)value.cycles=value.instructions=null;return value;}
function renderStatus(){if(serviceClosing)return;const job=state?.job;const running=job&&['running','stopping'].includes(job.status);$('#run').disabled=submitting||running||(typeof profileRunning==='function'&&profileRunning());$('#stop').disabled=!running||job.status==='stopping';$('#download').disabled=!runId;$('#run-dot').className='dot '+(running?'running':job?.status==='completed'?'':'neutral');$('#run-status').textContent=job?statusNames[job.status]||job.status:'尚未运行';$('#run-detail').textContent=job?`${job.id} · ${phaseNames[job.phase]||job.phase} · ${state?.run?.committed_ticks??0} / ${job.config.ticks} 轮`:'从上方配置开始一次可复现的实验';if(job?.error)error(job.error);}
function perfTable(){const rows=boot.stages.filter(s=>measured(s.id));if(!rows.length)return empty('运行实验后，这里显示每个阶段的真实测量值。');const max=Math.max(...rows.map(s=>measured(s.id).wall_ms),.001);return `<div class="table-wrap"><table><thead><tr><th>处理阶段</th><th class="num">调用</th><th class="num">处理行次</th><th class="num">处理行次 / s</th><th class="num">累计 / ms</th><th class="num">P95 / ms</th><th class="num">Instructions</th><th class="num">Cycles</th><th class="num">IPC</th><th class="num">CPU / ms</th><th class="num">缺页 minor / major</th><th class="num">切换 voluntary / involuntary</th></tr></thead><tbody>${rows.map(s=>{const m=measured(s.id);return `<tr class="clickable" data-stage="${s.id}"><td class="bar-cell">${esc(s.title)}<span class="bar-track"><span style="width:${m.wall_ms/max*100}%"></span></span></td><td class="num">${count(m.calls)}</td><td class="num">${count(m.rows)}</td><td class="num">${m.rows&&m.wall_ms?count(m.rows*1000/m.wall_ms):'—'}</td><td class="num">${fmt(m.wall_ms)}</td><td class="num">${fmt(m.p95_ms,3)}</td><td class="num">${short(m.instructions)}</td><td class="num">${short(m.cycles)}</td><td class="num">${fmt(m.ipc)}</td><td class="num">${fmt(m.user_ms+m.system_ms)}</td><td class="num">${count(m.minor_faults)} / ${count(m.major_faults)}</td><td class="num">${count(m.voluntary_switches)} / ${count(m.involuntary_switches)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function comparison(){if(!state?.comparison)return '';const cmp=state.comparison;return `<section class="panel" style="margin-top:20px"><div class="section-heading"><h2>C++ / Python 对照</h2>${badge(cmp.passed?'逐值校验通过':'未通过',cmp.passed?'':'warn')}</div><div class="compare-grid">${['cpp','python'].map(key=>{const data=cmp.runs[key];return `<div><h3>${key==='cpp'?'C++20 · C API':'Python · NumPy'}</h3><div class="capability"><span>活动总耗时</span><b class="mono">${fmt(data.metrics.total_active_ms)} ms</b></div><div class="capability"><span>三表写入</span><b class="mono">${fmt(data.metrics.write_ms)} ms</b></div><div class="capability"><span>DuckDB source_id</span><span class="mono">${esc(data.source_id)}</span></div></div>`;}).join('')}</div><div class="notice">${esc(cmp.note)} 对照耗时来自原程序，未混用上方带观测开销的阶段耗时。</div></section>`;}
function overview(){const t=total();const threads=Math.max(0,...Object.values(state?.trace?.stages||{}).map(s=>s.last.threads||0));const groups=[['generate','Python 生成'],['input_decode','输入解码'],['account_value','账户计算'],['market_write','三表事务'],['parquet_export','文件归档']];const progress=state?.job?100*(state.run?.committed_ticks||0)/state.job.config.ticks:0;return `<div class="metric-grid">${metric('C++ 处理阶段累计',state?fmt(t.wall_ms):'—','ms','排除生成、等待及观测日志 I/O','TIME')}${metric('执行指令',short(t.instructions),'','进程累计计数器的阶段差值','INST')}${metric('CPU 周期',short(t.cycles),'','来自 macOS 原生计数器','CYC')}${metric('每周期指令数',fmt(t.cycles?t.instructions/t.cycles:null),'IPC','Σ instructions / Σ cycles','RATIO')}</div><div class="overview-grid"><section class="panel"><div class="section-heading"><div><h2>数据流向</h2><p>沿实际调用顺序观察 · 点击阶段查看详情</p></div><span class="chip">C++ OBSERVER</span></div><div class="flow-mini">${groups.map(([id,title],i)=>`${i?'<span class="arrow">→</span>':''}<button data-stage="${id}"><span class="flow-index">0${i+1}</span><b>${title}</b><small>${groupTime(id)!=null?fmt(groupTime(id))+' ms':'等待运行'}</small></button>`).join('')}</div><div class="flow-note"><span>新闻：解析 → JSONL，独立于三表事务</span><span>提交后推进状态 → 分批归档</span></div><div class="progress"><span style="width:${progress}%"></span></div></section><section class="panel"><div class="section-heading"><div><h2>采集能力</h2><p>当前机器，当前运行</p></div><span class="mono muted">arm64</span></div><div class="capability"><span>instructions / cycles / IPC</span>${badge(t.valid?'本次已采集':'等待本次运行',t.valid?'':'gray')}</div><div class="capability"><span>线程数快照</span><span class="mono">${threads?threads+' · 观测最大值':'—'}</span></div><div class="capability"><span>cache / branch misses</span>${badge('未采集','warn')}</div><div class="capability"><span>输出正确性</span>${badge(state?.job?.validation?.passed?'校验通过':'等待校验',state?.job?.validation?.passed?'':'gray')}</div></section></div><section class="panel"><div class="section-heading"><div><h2>阶段性能明细</h2><p>进程级前后快照 · 点击任一行定位源码 · 横向滚动查看全部指标</p></div><span class="chip">LIVE MEASUREMENTS</span></div>${perfTable()}<div class="notice">macOS 原生计数器，非 Linux perf stat 输出。短阶段受采样开销影响；线程数表示存在的线程，并不证明并行利用率。缺失硬件事件显示为不可用。</div></section>${comparison()}`;}
function chart(samples){if(!samples?.length)return '';const max=Math.max(...samples,.001);const points=samples.map((s,i)=>`${10+(samples.length===1?0:i/(samples.length-1))*780},${95-s/max*80}`).join(' ');return `<svg class="sparkline" viewBox="0 0 800 105" preserveAspectRatio="none" role="img" aria-label="逐次调用耗时折线图"><line x1="0" y1="95" x2="800" y2="95" stroke="#d8e6d8"/><polyline points="${points}" stroke="#428461" stroke-width="2" fill="none" vector-effect="non-scaling-stroke"/>${samples.length===1?`<circle cx="10" cy="${95-samples[0]/max*80}" r="3" fill="#428461"/>`:''}</svg><div class="small muted">按调用顺序绘制 · 最大 ${fmt(max,3)} ms · 共 ${samples.length} 次</div>`;}
function pipeline(){const s=stageInfo(selectedStage)||boot.stages[0];const m=measured(s.id);return `<div class="split"><aside class="choice-list panel">${boot.stages.map((x,i)=>`<button class="choice ${x.id===s.id?'selected':''}" data-select-stage="${x.id}"><span class="mini-number">${measured(x.id)?fmt(measured(x.id).wall_ms,1)+' ms':'—'}</span><b>${String(i+1).padStart(2,'0')} ${esc(x.title)}</b><span>${esc(x.id)}</span></button>`).join('')}</aside><section class="panel pipeline-detail"><div class="section-heading"><div><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p></div>${badge(stageStatus(s.id),stageStatus(s.id)==='运行中'?'':m?'':'gray')}</div><div class="metric-grid">${metric('阶段累计',fmt(m?.wall_ms),'ms',`${m?.calls??0} 次调用`)}${metric('Instructions',short(m?.instructions),'','原始计数见导出报告')}${metric('Cycles',short(m?.cycles),'','按进程累计差值')}${metric('IPC',fmt(m?.ipc),'','仅在 cycles > 0 时计算')}${metric('CPU 时间',m?fmt(m.user_ms+m.system_ms):'—','ms','user + system')}${metric('P95 调用耗时',fmt(m?.p95_ms,3),'ms','nearest-rank；小样本仅供观察')}</div>${chart(m?.samples)}${m?`<div class="data-meta"><div>调用行次<strong>${count(m.rows)}</strong></div><div>最后 RSS<strong>${fmt(m.last.rss_bytes/1024/1024)} MiB</strong></div><div>最后线程数<strong>${count(m.last.threads)}</strong></div><div>缺页 minor / major<strong>${count(m.minor_faults)} / ${count(m.major_faults)}</strong></div></div>`:empty('该阶段尚无数据；阶段未触发时不会伪造样本。')}<div class="notice">${s.id==='generate'?'此阶段在独立 Python 进程中采集，未混入 C++ 指令总数。':s.id==='parquet_export'?'归档阶段包含三张表导出、manifest 和目录发布；内部子操作未单独计数。':s.id==='pace_wait'?'这是回放等待时间，不是数据处理延迟。':'硬件计数覆盖该阶段时间窗口内的整个 C++ 进程，包括 DuckDB 内部线程。采样调用有开销；不作为单函数零开销测量。'}</div>${sourceBlock(s.source,28)}<div class="small muted">上方为原实现位置；观测边界位于 <button class="text-button" data-source="database_exp/workbench/native/runner.cpp" data-line="1">workbench/native/runner.cpp ↗</button></div></section></div>${eventLog()}`;}
function schemas(){const t=boot.tables.find(x=>x.name===selectedTable)||boot.tables[0];return `<div class="split"><aside class="panel choice-list">${boot.tables.map(x=>`<button class="choice ${x.name===t.name?'selected':''}" data-table="${x.name}"><b class="mono">${esc(x.name)}</b><span>${esc(x.title)} · ${x.columns.length} 字段</span></button>`).join('')}</aside><section class="panel"><div class="schema-head"><div><h2>${esc(t.name)}</h2><span class="muted small">${esc(t.title)} · ${esc(t.kind)}</span></div><input id="field-search" type="search" placeholder="搜索字段 / 类型" aria-label="搜索字段"></div><div class="notice">${t.family==='stream'?'当前流式实验使用的持久化表。三张表在同一事务提交；未定义外键，不把 team_id / instrument_id 的逻辑关联画成数据库外键。':t.family==='legacy'?'独立 duckdb_parquet 示例中的内存中间表，用于分批导出 Parquet；不是当前流式实验的第四张持久表。':'新闻保存为 JSONL 文件，不属于 DuckDB 三表事务。字段列表已与 parser 返回对象核对；字段类型是解析器输出约定。'}</div><div class="table-wrap"><table id="field-table"><thead><tr><th>字段名称</th><th>类型</th><th>约束</th><th>含义 / 单位</th></tr></thead><tbody>${t.columns.map(c=>`<tr data-field="${esc((c.name+' '+c.type+' '+c.description).toLowerCase())}"><td class="mono">${esc(c.name)}</td><td class="mono schema-type">${esc(c.type)}</td><td>${c.primary?badge('PK'):''} ${t.family==='news'?badge('解析器约定','gray'):!c.nullable?badge('NOT NULL','gray'):badge('NULLABLE','gray')}</td><td class="field-description">${esc(c.description)}</td></tr>`).join('')}</tbody></table></div><div class="section-heading" style="margin-top:25px"><h2>完整约束</h2><span class="muted small">${t.family==='news'?'非数据库约束':'来自 duckdb_constraints()'}</span></div>${t.constraints.length?t.constraints.map(c=>`<div class="constraint">${esc(c.columns.join(', '))} · ${esc(c.text)}</div>`).join(''):empty('该对象没有数据库约束。')}<details><summary class="small" style="cursor:pointer;margin-top:20px">展开 DDL / 格式约定</summary><pre class="code">${esc(t.ddl)}</pre></details>${sourceBlock(t.source,12)}</section></div>`;}
function dataView(){return `<section class="panel"><div class="section-heading"><div><h2>数据预览</h2><p>输入记录和数据库结果分别预览；每张表最多显示 50 行。</p></div><span class="chip">SEED 42</span></div><div class="data-controls"><label>查看对象<select id="data-kind"><option value="input" ${dataKind==='input'?'selected':''}>Python 原始输入</option><option value="output" ${dataKind==='output'?'selected':''}>已落盘结果</option></select></label><label>数据类型<select id="data-table">${(dataKind==='input'?[['market','行情'],['trades','成交'],['accounts','账户参考值'],['news','新闻原文']]:[['market_quotes','market_quotes'],['team_trades','team_trades'],['account_snapshots','account_snapshots'],['news.jsonl','news.jsonl']]).map(([key,title])=>`<option value="${key}" ${dataTable===key?'selected':''}>${title}</option>`).join('')}</select></label>${dataKind==='input'?`<label class="tick">输入 tick<input id="data-tick" type="number" min="0" max="${(state?.job?.config.ticks||1)-1}" value="${dataTick}"></label>`:''}<button class="button secondary" id="load-data">读取数据 ↻</button></div><div id="data-result">${empty(runId?'正在读取…':'先运行一次实验，再查看输入和输出。')}</div></section>`;}
function renderRecords(records){if(!records.length)return empty('当前 tick / 数据表没有记录。');if(typeof records[0]==='string')return records.map(r=>`<pre class="code json-block">${esc(r)}</pre>`).join('');const keys=Object.keys(records[0]);return `<div class="data-preview"><table><thead><tr>${keys.map(k=>`<th class="mono">${esc(k)}</th>`).join('')}</tr></thead><tbody>${records.slice(0,50).map(r=>`<tr>${keys.map(k=>{const value=typeof r[k]==='object'?JSON.stringify(r[k]):String(r[k]);return `<td class="mono" title="${esc(value)}">${esc(value)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;}
async function loadData(){if(!runId||view!=='data')return;const id=runId;dataTable=$('#data-table').value;dataTick=Number($('#data-tick')?.value||0);try{const value=await api(`/api/data?id=${id}&kind=${dataKind}&table=${encodeURIComponent(dataTable)}&tick=${dataTick}`);if(view!=='data'||runId!==id)return;if(value.pending){$('#data-result').innerHTML=empty(value.message);return;}if(dataKind==='input'){$('#data-result').innerHTML=`<div class="data-meta"><div>生成方式<strong>Python + NumPy</strong></div><div>随机种子<strong>${value.metadata.seed}</strong></div><div>输入轮数<strong>${value.metadata.requested_seconds/value.metadata.tick_seconds}</strong></div><div>文件大小<strong>${fmt(value.bytes/1024)} KiB</strong></div></div><p class="hash">SHA-256 ${esc(value.sha256)}</p>${renderRecords(value.tick[dataTable])}<div class="notice">账户输入是参考快照；C++ 会从成交和行情重新计算。时间字段 *_us / event_time 使用 UTC Unix 微秒；价格使用整数分。此回放保留固定 ingested_us，1 秒模式只控制节拍。</div><details><summary class="small">查看本轮完整原始 JSON</summary><pre class="code json-block">${esc(JSON.stringify(value.tick,null,2))}</pre></details>`;}else{$('#data-result').innerHTML=renderRecords(value)+'<div class="notice">来自本次运行已关闭的 DuckDB / JSONL；整数超过 JavaScript 精确范围时，API 使用字符串传输以保留原值。</div>';}}catch(e){error(e.message);}}
function evidenceView(){return `<div class="notice">观测入口复用原有业务函数，逐阶段计数属于新加的观测层。未新增多线程计算或 SIMD 算法，也没有把库具备某种能力当作本次运行已经使用的证据。</div><div class="evidence-grid">${boot.evidence.map(e=>`<section class="panel evidence-card"><div class="section-heading"><span class="chip">${esc(e.id.toUpperCase())}</span>${badge(e.status,e.id==='simd'?'warn':'')}</div><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p>${sourceBlock(e.source,e.id==='batch'?24:12)}</section>`).join('')}</div><section class="panel" style="margin-top:20px"><div class="section-heading"><div><h2>本次编译器报告</h2><p>直接读取 build/build.log 中对应业务源码的 loop-vectorize remarks</p></div>${badge(boot.build.remarks?'报告可读取':'没有匹配报告','gray')}</div><pre class="code">${esc(boot.build.remarks||'暂无可用报告；不推断 SIMD 是否启用。')}</pre><div class="notice">${esc(boot.build.note)}</div><div class="hash">Observer binary SHA-256: ${esc(boot.build.manifest?.binary_sha256||'未记录')}</div><pre class="code">${esc(boot.build.manifest?.compiler||'未记录')}</pre></section><section class="panel" style="margin-top:20px"><div class="section-heading"><h2>采集口径与来源</h2></div><div class="capability"><span>采集接口</span><span class="mono">${esc(boot.environment.counter_source)}</span></div><div class="capability"><span>Instruments / xctrace</span>${badge(boot.environment.xctrace?'可调用':'当前不可调用',boot.environment.xctrace?'':'warn')}</div><pre class="code">${esc(boot.environment.xctrace_detail)}</pre><p class="small muted">本机原生接口可采集 instructions / cycles；cache misses、branch misses 和 CPU migrations 未通过本接口采集，不以零值替代。短阶段数据受采样调用和内核统计粒度影响。</p>${boot.environment.references.map(r=>`<p class="small"><a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.title)} ↗</a></p>`).join('')}</section>`;}
async function historyView(){const runs=await api('/api/runs');if(view!=='history')return;$('#content').innerHTML=`<section class="panel"><div class="section-heading"><h2>本地运行记录</h2><span class="chip">${runs.length} RUNS</span></div>${runs.length?runs.map(r=>`<div class="history-row"><div class="mono">${esc(r.id)}<small>${r.created_at?esc(new Date(r.created_at).toLocaleString('zh-CN')):'正在创建'}</small></div><div>${r.config.symbols} 标的 × ${r.config.ticks} 轮<small>${r.config.teams} 团队 · ${r.config.threads} DuckDB 线程预算</small></div><div>${badge(statusNames[r.status]||r.status,['failed','interrupted'].includes(r.status)?'warn':'')}</div><div class="mono">${r.elapsed_seconds?fmt(r.elapsed_seconds,1)+' s':'—'}</div><button class="button secondary" data-run-id="${r.id}">查看运行</button></div>`).join(''):empty('还没有实验记录。')}</section>`;}
function render(){if(serviceClosing||!boot)return;const [label,title,description]=pages[view];$('#page-label').textContent=label;$('#page-title').textContent=title;$('#page-description').textContent=description;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=view==='overview'?overview():view==='pipeline'?pipeline():view==='schema'?schemas():view==='data'?dataView():view==='evidence'?evidenceView():empty('读取运行记录…');$('.runbar').hidden=view==='profiles';$('.run-status').hidden=view==='profiles';if(view==='profiles')loadProfiles().catch(e=>error(e.message));if(view==='data')loadData();if(view==='history')historyView().catch(e=>error(e.message));}
function switchView(next){view=pages[next]?next:'overview';history.replaceState(null,'','#'+view);render();}
async function refresh(){if(serviceClosing||!runId||refreshing)return;refreshing=true;try{state=await api('/api/state?id='+runId);if(serviceClosing)return;renderStatus();if(['overview','pipeline'].includes(view))render();$('#connection').textContent='本机已连接';}catch(e){if(!serviceClosing){error(e.message);$('#connection').textContent='连接失败';}}finally{refreshing=false;}}
async function openSource(file,line=1){try{const source=await api('/api/source?file='+encodeURIComponent(file));$('#source-title').textContent=source.file;$('#source-hash').textContent='SHA-256 '+source.sha256;$('#source-code').innerHTML=source.text.split('\n').map((text,i)=>`<span id="source-line-${i+1}" style="display:block;${i+1===Number(line)?'background:#e9f4e9':''}"><span style="display:inline-block;width:45px;color:#9ba99d">${i+1}</span>${esc(text)}</span>`).join('');$('#source-dialog').showModal();$('#source-line-'+line)?.scrollIntoView({block:'center'});}catch(e){error(e.message);}}
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.view)switchView(target.dataset.view);if(target.dataset.stage){selectedStage=target.dataset.stage;switchView('pipeline');}if(target.dataset.selectStage){selectedStage=target.dataset.selectStage;render();}if(target.dataset.table){selectedTable=target.dataset.table;render();}if(target.dataset.source)openSource(target.dataset.source,target.dataset.line);if(target.dataset.runId){runId=target.dataset.runId;localStorage.setItem('database-lab-run',runId);state=null;error('');switchView('overview');refresh();}if(target.id==='load-data')loadData();});
document.addEventListener('input',event=>{if(event.target.id==='field-search'){const query=event.target.value.toLowerCase();document.querySelectorAll('[data-field]').forEach(row=>row.hidden=!row.dataset.field.includes(query));}});
document.addEventListener('change',event=>{if(event.target.id==='data-kind'){dataKind=event.target.value;dataTable=dataKind==='input'?'market':'market_quotes';render();}if(event.target.id==='data-table'||event.target.id==='data-tick')loadData();});
$('#run-form').addEventListener('submit',async event=>{event.preventDefault();error('');submitting=true;renderStatus();try{const form=new FormData(event.target),config={};for(const key of ['ticks','symbols','teams','threads','export_every'])config[key]=Number(form.get(key));config.mode=form.get('mode');config.compare=form.has('compare');const value=await api('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(config)});runId=value.id;state=null;error('');localStorage.setItem('database-lab-run',runId);switchView('overview');await refresh();}catch(e){error(e.message);}finally{submitting=false;renderStatus();}});
$('#stop').addEventListener('click',async()=>{try{await api('/api/stop',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:runId})});$('#stop').disabled=true;await refresh();}catch(e){error(e.message);}});
$('#refresh').addEventListener('click',()=>{error('');refresh();if(view==='history')historyView();if(view==='data')loadData();if(view==='profiles')loadProfiles().catch(e=>error(e.message));});
$('#download').addEventListener('click',async()=>{try{const data=await api('/api/report?id='+runId);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='database-lab-'+runId+'.json';a.click();URL.revokeObjectURL(url);}catch(e){error(e.message);}});
$('#close-dialog').addEventListener('click',()=>$('#source-dialog').close());
async function init(){try{boot=await api('/api/bootstrap');if(serviceClosing)return;$('#host-label').textContent=`${boot.environment.arch} · DuckDB ${boot.environment.duckdb}`;$('#connection').textContent='本机已连接';runId=localStorage.getItem('database-lab-run');if(!runId){const runs=await api('/api/runs');runId=runs[0]?.id||null;}view=location.hash.slice(1)||'overview';if(!pages[view])view='overview';render();await refresh();setInterval(()=>{if(state?.job&&['completed','failed','stopped','interrupted'].includes(state.job.status))return;refresh();},750);}catch(e){if(!serviceClosing){error(e.message);$('#connection').textContent='连接失败';}}}
init();
